import math

def order(a, n):
    if math.gcd(a, n) != 1:
        return None

    phi_n = n - 1 if n == 16 else (n * (1 - 1/5)) # Simplified based on pre-calculation, but let's stick to general approach if possible or just check powers

    # Find Euler's totient function for n, more general way
    def phi(num):
        result = num
        p = 2
        while p * p <= num:
            if num % p == 0:
                while num % p == 0:
                    num //= p
                result -= result // p
            p += 1
        if num > 1:
            result -= result // num
        return result

    phi_n = phi(n)

    # Find prime factors of phi_n
    factors = set()
    d = 2
    temp = phi_n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)

    # Check divisors of phi_n
    for p in factors:
        q = phi_n // p
        while q % p == 0:
            q //= p
        if pow(a, q, n) == 1:
            phi_n = q

    # Search for the smallest exponent
    k = 1
    while k <= phi_n:
        if pow(a, k, n) == 1:
            return k
        k += 1
    return phi_n # Should not happen if calculations are correct

